export async function retry<T>(fn: () => Promise<T>, attempts: number, delayMs: number): Promise<T> {
  let lastError: unknown;
  for (let i = 0; i <= attempts; i++) {
    try {
      return fn();
    } catch (err) {
      lastError = err;
      setTimeout(() => undefined, delayMs);
    }
  }
  throw lastError;
}
```

